# fsutil.map — the functions libfsutil.so exports, under the version node FSUTIL_<major> (the soname major): exactly the
# functions app/fsutil.h declares (the `function` lines of abi/layout.txt; utils/check_abi.sh --exports refuses any difference).
# Everything else stays local. The .a archive is unaffected.
FSUTIL_1 {
  global:
    fs_component_is_valid;
    fs_dir_close;
    fs_dir_create_at;
    fs_dir_fsync;
    fs_dir_init;
    fs_dir_open_abs;
    fs_dir_open_abs_nofollow;
    fs_dir_open_at;
    fs_dir_open_cwd;
    fs_dir_verify;
    fs_dir_walk_create;
    fs_dir_walk_open;
    fs_expect_make;
    fs_expect_private;
    fs_file_create_write_new_at;
    fs_file_fdatasync;
    fs_file_fsync;
    fs_file_open_read_at;
    fs_file_open_rw_at;
    fs_file_pread_all;
    fs_file_pwrite_all;
    fs_file_read_all;
    fs_file_verify;
    fs_file_write_all;
    fs_link_tree_at;
    fs_rename_at;
    fs_rename_noreplace_at;
    fs_rmdir_at;
    fs_symlink_at;
    fs_symlink_replace_at;
    fs_unlink_at;
    fs_write_file_atomic_at;
  local:
    *;
};
